const items = $input.all();
let label = 'AI Newsletters';
try {
  const first = items[0] && items[0].json;
  if (Array.isArray(first) && first.length > 0) label = first[0].value || label;
  else if (first && typeof first === 'object' && first.value) label = first.value;
} catch (e) {}
return [{ json: { gmail_label: label } }];

const items = $input.all();
const first = (items[0] && items[0].json) || {};
const messages = (first.messages || []).slice(0, 50);
return [{ json: { ids: messages.map(m => m.id), gmail_listed: messages.length } }];

function decodePart(data) { try { return Buffer.from(String(data || '').replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf-8'); } catch (e) { return ''; } }
function findBody(part) {
  if (!part) return '';
  const mt = (part.mimeType || '').toLowerCase();
  if (mt === 'text/plain' && part.body && part.body.data) return decodePart(part.body.data);
  if (mt === 'text/html' && part.body && part.body.data) return decodePart(part.body.data).replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<script[\s\S]*?<\/script>/gi, '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/\s+/g, ' ');
  if (Array.isArray(part.parts)) {
    for (const p of part.parts) {
      const got = findBody(p);
      if (got) return got;
    }
  }
  return '';
}
const items = $input.all();
let stats = { gmail_listed: 0, gmail_new: 0, gmail_overflow: 0 };
try { const e = $('Emit Unseen').first().json; stats = { gmail_listed: e.gmail_listed || 0, gmail_new: e.gmail_new || 0, gmail_overflow: e.gmail_overflow || 0 }; } catch (err) {}
const newsletters = [];
for (const it of items) {
  const j = it.json || {};
  if (j._empty || j.error || !j.payload) continue;
  const headers = j.payload.headers || [];
  const getH = (n) => { const h = headers.find(x => (x.name || '').toLowerCase() === n.toLowerCase()); return h ? h.value : ''; };
  const body = (findBody(j.payload) || j.snippet || '').slice(0, 12000);
  if (!body || body.length < 80) continue;
  const fromRaw = getH('From');
  const fm = fromRaw.match(/^\s*"?([^"<]*)"?\s*<([^>]+)>\s*$/);
  const display_name = ((fm ? fm[1] : fromRaw.split('@')[0]) || '').trim() || fromRaw.trim();
  const from_email = ((fm ? fm[2] : fromRaw) || '').trim().toLowerCase();
  let date_iso = null;
  try { const d = new Date(getH('Date')); if (!isNaN(d.getTime())) date_iso = d.toISOString(); } catch (e2) {}
  newsletters.push({
    id: j.id,
    thread_id: j.threadId,
    subject: getH('Subject'),
    from: fromRaw,
    from_email,
    display_name,
    date_iso,
    body,
    url: 'https://mail.google.com/mail/u/0/#inbox/' + (j.threadId || j.id),
  });
}
return [{ json: { newsletters, gmail_count: newsletters.length, gmail_listed: stats.gmail_listed, gmail_new: stats.gmail_new, gmail_overflow: stats.gmail_overflow } }];

const items = $input.all();
let folder_id = '';
try {
  const first = items[0] && items[0].json;
  if (Array.isArray(first) && first.length > 0) folder_id = first[0].value || '';
  else if (first && typeof first === 'object') folder_id = first.value || '';
} catch (e) {}
const ok = folder_id && !/YOUR_|PLACEHOLDER|HERE/i.test(folder_id) && folder_id.length >= 12;
return [{ json: { folder_id: ok ? folder_id : '' } }];

const items = $input.all();
const first = (items[0] && items[0].json) || {};
const READABLE = new Set([
  'application/vnd.google-apps.document',
  'text/plain',
  'text/markdown',
  'application/vnd.google-apps.spreadsheet',
  'image/jpeg',
  'image/png',
  'image/webp',
  'image/gif',
  'application/pdf',
]);
const files = (first.files || []).filter(f => READABLE.has(f.mimeType));
if (files.length === 0) return [{ json: { _empty: true } }];
return files.map(f => ({ json: { id: f.id, name: f.name, mimeType: f.mimeType, modifiedTime: f.modifiedTime } }));

const items = $input.all();
const list = $('Drive Filter Readable').all().map(i => i.json);
const TEXT_MIMES = new Set(['application/vnd.google-apps.document','text/plain','text/markdown','application/vnd.google-apps.spreadsheet']);
const IMAGE_MIMES = new Set(['image/jpeg','image/png','image/webp','image/gif']);
const PDF_MIME = 'application/pdf';
const docs = [];
const images = [];
const pdfs = [];

for (let i = 0; i < items.length; i++) {
  const meta = list[i] || {};
  const mime = meta.mimeType || '';
  const item = items[i] || {};
  let buf = null;
  if (item.binary && item.binary.data) {
    try { buf = await this.helpers.getBinaryDataBuffer(i, 'data'); } catch (e) { buf = null; }
  }
  const urlFor = (id) => mime === 'application/vnd.google-apps.document' ? 'https://docs.google.com/document/d/' + id + '/edit'
    : mime === 'application/vnd.google-apps.spreadsheet' ? 'https://docs.google.com/spreadsheets/d/' + id + '/edit'
    : 'https://drive.google.com/file/d/' + id + '/view';

  if (TEXT_MIMES.has(mime)) {
    let body = buf ? buf.toString('utf-8') : '';
    if ((!body || body.length < 80) && item.json && typeof item.json.data === 'string') body = item.json.data;
    body = String(body || '').replace(/\u0000/g, '').slice(0, 8000);
    if (body && body.length >= 80) {
      docs.push({ id: meta.id, name: meta.name, mime_type: mime, modified: meta.modifiedTime, body, url: urlFor(meta.id) });
    }
  } else if (IMAGE_MIMES.has(mime) && buf) {
    images.push({ id: meta.id, name: meta.name, mime_type: mime, modified: meta.modifiedTime, base64: buf.toString('base64'), url: 'https://drive.google.com/file/d/' + meta.id + '/view' });
  } else if (mime === PDF_MIME && buf) {
    pdfs.push({ id: meta.id, name: meta.name, mime_type: mime, modified: meta.modifiedTime, base64: buf.toString('base64'), url: 'https://drive.google.com/file/d/' + meta.id + '/view' });
  }
}
return [{ json: { drive_docs: docs, drive_images: images, drive_pdfs: pdfs, drive_count: docs.length + images.length + pdfs.length } }];

let newsletters = [];
try { const g = $('Apply Canonical Labels').first(); if (g && g.json && Array.isArray(g.json.newsletters)) newsletters = g.json.newsletters; } catch (e) {}
if (!newsletters.length) { try { const g2 = $('Gmail Extract Body').first(); if (g2 && g2.json && Array.isArray(g2.json.newsletters)) newsletters = g2.json.newsletters; } catch (e) {} }
let drive_docs = [], drive_images = [], drive_pdfs = [];
try { const a = $('Drive Aggregate').first(); if (a && a.json) { drive_docs = a.json.drive_docs || []; drive_images = a.json.drive_images || []; drive_pdfs = a.json.drive_pdfs || []; } } catch (e) {}
if (!drive_docs.length && !drive_images.length && !drive_pdfs.length) {
  try { const s = $('Drive Skip Empty').first(); if (s && s.json && Array.isArray(s.json.drive_docs)) drive_docs = s.json.drive_docs; } catch (e) {}
}
const pillarsRaw = $('Load Pillars').all().map(i => i.json);
const pillars = Array.isArray(pillarsRaw[0]) ? pillarsRaw[0] : pillarsRaw;
const briefRaw = $('Load Cleo Brief').all().map(i => i.json);
const briefArr = Array.isArray(briefRaw[0]) ? briefRaw[0] : briefRaw;
const brief = (briefArr[0] && briefArr[0].brief_content) || '';
const cfgRaw = $('Load Thresholds').all().map(i => i.json);
const cfgArr = Array.isArray(cfgRaw[0]) ? cfgRaw[0] : cfgRaw;
const cfg = {};
for (const row of cfgArr) cfg[row.key] = row.value;
const minFit = parseInt(cfg.cleo_inspiration_min_brand_fit || '6', 10);
let yieldRows = [];
try {
  const yRaw = $('Load Source Yield').all().map(i => i.json);
  const yArr = Array.isArray(yRaw[0]) ? yRaw[0] : yRaw;
  yieldRows = yArr.filter(r => r && r.newsletter_key && r.newsletter_key !== 'unlabelled');
} catch (e) {}
const trackBlock = yieldRows.map(r => '- ' + r.newsletter_key + ': ' + r.seeds + ' seeds, ' + r.advanced + ' advanced to drafting or beyond, ' + r.buried + ' buried, ' + r.recurrences + ' recurrences').join('\n');

const pillarsBlock = pillars.map(p => {
  const gl = p.good_looks_like || {};
  const ap = (p.anti_patterns || []).map(x => '  - ' + x).join('\n');
  const er = (p.evidence_required || []).map(x => '  - ' + x).join('\n');
  return '### ' + p.name + ' (id: ' + p.id + ')\n' +
         '**Description:** ' + p.description + '\n' +
         '**Voice:** ' + (gl.voice || '') + '\n' +
         '**Source patterns:** ' + (gl.source_patterns || '') + '\n' +
         '**Angle patterns:** ' + (gl.angle_patterns || '') + '\n' +
         '**Good examples:** ' + (gl.good_examples || '') + '\n' +
         '**Anti-patterns (REJECT if matched):**\n' + ap + '\n' +
         '**Evidence required (at least one must be present):**\n' + er;
}).join('\n\n');

const newslettersBlock = newsletters.length === 0
  ? '(no NEW newsletters since the last run; previously-read messages are never re-read)'
  : newsletters.map((n, i) => '--- NEWSLETTER ' + (i+1) + ' ---\nFROM: ' + (n.canonical_label || n.from || 'unknown') + '\nKEY: ' + (n.newsletter_key || 'unregistered') + '\nSUBJECT: ' + (n.subject || '') + '\nURL: ' + (n.url || '') + '\nBODY:\n' + n.body).join('\n\n');

const docsBlock = drive_docs.length === 0
  ? '(no inspiration text docs in lookback window)'
  : drive_docs.map((d, i) => '--- DOC ' + (i+1) + ' ---\nFILE: ' + (d.name || '') + ' (' + (d.mime_type || '') + ')\nURL: ' + (d.url || '') + '\nBODY:\n' + d.body).join('\n\n');

const imagesIntro = drive_images.length === 0 && drive_pdfs.length === 0
  ? '(no image / PDF screenshots in lookback window)'
  : 'The following ' + (drive_images.length + drive_pdfs.length) + ' file(s) are screenshots or PDFs from Krish inspiration folder. Most will be LinkedIn post screenshots. For each, EXTRACT: (a) who posted (name + handle/title if visible), (b) the post body/headline, (c) any visible engagement metrics, (d) why the post matters to one of Krish pillars. Apply the SAME pillar bar to image-derived seeds as to text-derived seeds. Source label should be the filename. Source url should be the Drive view url provided.';

const systemPrompt =
  (brief ? 'AGENT BRIEF:\n' + brief + '\n\n---\n\n' : '') +
  'You are reading raw inspiration material for Krish. Material may include newsletter bodies, text documents from a Drive folder, AND screenshots (mostly LinkedIn posts) or PDFs. Extract publish-ready content seeds mapped to one of Krish five pillars. The bar is high. Most input does NOT contain a seed worth surfacing. If nothing qualifies, return an empty array [].\n\n' +
  '## KRISH PILLARS\n\n' + pillarsBlock + '\n\n' +
  '## KRISH VOICE RULES\n' +
  '- Declarative and specific. No hedging.\n' +
  '- Real numbers, real artifacts, real anecdotes.\n' +
  '- One sharp thought per piece. No bullet-soup.\n' +
  '- NO em dashes anywhere. Use commas, colons, parentheses, or line breaks.\n' +
  '- Plain English. Banned: leveraging, unlocking, delve into, fast-paced world, navigating, robust, synergies.\n\n' +
  '## THE BAR (CLO-020 v2)\n' +
  'Score each candidate brand_fit_score 1-10. Auto-reject below ' + minFit + '. Promote to researching at 9-10.\n' +
  '- 10: Krish exact voice; novel thesis with real artifact; clear distribution lane; perfect pillar fit.\n' +
  '- 9: Strong fit, original angle, satisfies pillar evidence_required, no anti-pattern triggers.\n' +
  '- 8: Plausible content needs one more piece of evidence.\n' +
  '- 7: Real candidate but generic in places.\n' +
  '- 6: Borderline. Surface but flag.\n' +
  '- <=5: Drop. Set is_idea=false.\n\n' +
  '## EVIDENCE FLOOR\n' +
  'Reject any seed that does not satisfy its pillar evidence_required list. List evidence in evidence_present array.\n\n' +
  '## ANTI-PATTERN FLOOR\n' +
  'Reject any seed whose framing matches any of the pillar anti_patterns. Score <=4 if it does.\n\n' +
  '## SOURCE TRACK RECORD (how each newsletter has performed as a seed source)\n' +
  (trackBlock || '(no history yet)') + '\n' +
  'Seeds from sources whose output keeps getting buried need a HIGHER bar. Sources whose seeds advance to drafting deserve closer reading.\n\n' +
  '## TEMPORAL CLASS (news vs trend)\n' +
  'Classify every seed:\n' +
  '- ephemeral: a single event (one launch, one funding round, one benchmark result). Worth an opinion this week, dead in two.\n' +
  '- developing: a storyline still unfolding across weeks; evidence is accumulating.\n' +
  '- durable: a structural change in how AI-first businesses operate; still true next quarter.\n' +
  'Set expires_in_days honestly: ephemeral 5-14, developing 21-45, durable null.\n\n' +
  '## IMAGE / SCREENSHOT HANDLING\n' +
  imagesIntro + '\n\n' +
  '## OUTPUT\n' +
  'Strict JSON array. No preamble, no markdown fence.\n' +
  '[\n' +
  '  {\n' +
  '    "is_idea": true,\n' +
  '    "idea": "headline-style framing in Krish voice (12+ chars)",\n' +
  '    "thesis": "1-2 sentences. Why this lands now.",\n' +
  '    "pillar_id": "pillar:agentic_ops",\n' +
  '    "distribution": ["linkedin", "newsletter", "techonomic"],\n' +
  '    "brand_fit_score": 9,\n' +
  '    "confidence": 0.9,\n' +
  '    "quality_score": "green",\n' +
  '    "temporal_class": "ephemeral | developing | durable",\n' +
  '    "expires_in_days": 10,\n' +
  '    "newsletter_key": "the KEY provided with the newsletter this seed came from, null for doc/screenshot seeds",\n' +
  '    "source_label": "the canonical FROM label provided (or filename / post author for doc and screenshot seeds)",\n' +
  '    "source_url": "https://...",\n' +
  '    "source_excerpt": "<=280 chars of the original or transcribed image content",\n' +
  '    "evidence_present": ["named entity: X", "figure: $Y", "date: Z"],\n' +
  '    "image_source": null,\n' +
  '    "poster_name": null,\n' +
  '    "poster_handle": null,\n' +
  '    "rejection_reason": null\n' +
  '  }\n' +
  ']\n\n' +
  'For seeds extracted from a screenshot: set image_source to the filename, fill poster_name + poster_handle from what is visible in the image. For text-derived seeds: leave image_source, poster_name, poster_handle as null.\n\n' +
  'If nothing qualifies, return [].';

const userContent = [];
const textBlock =
  '=== NEW NEWSLETTERS (unread since last run, full bodies) ===\n' + newslettersBlock + '\n\n' +
  '=== INSPIRATION TEXT DOCS (last 14 days) ===\n' + docsBlock + '\n\n' +
  '=== INSPIRATION IMAGES / PDFs (last 14 days) ===\n' + (drive_images.length + drive_pdfs.length === 0 ? '(none)' : 'See attached image and PDF blocks below. Filenames: ' + [...drive_images, ...drive_pdfs].map(x => x.name).join(', ')) + '\n\n' +
  'Extract seeds now. Strict JSON array only.';

userContent.push({ type: 'text', text: textBlock });
for (const img of drive_images.slice(0, 10)) {
  userContent.push({ type: 'image', source: { type: 'base64', media_type: img.mime_type, data: img.base64 } });
  userContent.push({ type: 'text', text: '(above image: ' + img.name + ' - url: ' + img.url + ')' });
}
for (const pdf of drive_pdfs.slice(0, 5)) {
  userContent.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: pdf.base64 } });
  userContent.push({ type: 'text', text: '(above PDF: ' + pdf.name + ' - url: ' + pdf.url + ')' });
}

const anthropic_body = {
  model: 'claude-sonnet-4-6',
  max_tokens: 8000,
  temperature: 0.2,
  system: systemPrompt,
  messages: [{ role: 'user', content: userContent }],
};
return [{ json: { anthropic_body, newsletters_count: newsletters.length, docs_count: drive_docs.length, images_count: drive_images.length, pdfs_count: drive_pdfs.length, min_brand_fit: minFit, pillars_count: pillars.length } }];

const items = $input.all();
const src = (items[0] && items[0].json) || {};
const body = src.anthropic_body || {};
const msgs = body.messages || [];
let promptText = (body.system || '') + '\n\n';
for (const m of msgs) {
  const c = typeof m.content === 'string' ? m.content : JSON.stringify(m.content);
  promptText += (m.role === 'user' ? c : '[assistant]: ' + c) + '\n\n';
}
const gemini_body = {
  contents: [{ parts: [{ text: promptText.trim() }] }],
  generationConfig: { maxOutputTokens: body.max_tokens || 3000, temperature: body.temperature || 0.2 },
};
return [{ json: { gemini_body } }];

const items = $input.all();
const d = (items[0] && items[0].json) || {};
let raw = '';
let model_used = 'claude-sonnet-4-6';
if (d.content && d.content[0] && d.content[0].text) { raw = d.content[0].text; }
else if (d.candidates && d.candidates[0]) { raw = ((d.candidates[0].content || {}).parts || [{}])[0].text || ''; model_used = 'gemini-2.5-pro-fallback'; }
const usage = d.usage || {};
const inputTokens = usage.input_tokens || 0;
const outputTokens = usage.output_tokens || 0;
const cost_usd = (inputTokens / 1000000) * 3.0 + (outputTokens / 1000000) * 15.0;
const minFit = parseInt($('Build Extraction Prompt').first().json.min_brand_fit || 6, 10);
const BLACKLIST = [/^how i /i, /^the (top|best) \d/i, /^\d+ ways /i, /^lessons (from|i learned)/i, /the future of /i, /^why .* matters$/i];
let arr = [];
try {
  const m = raw.match(/\[[\s\S]*\]/);
  if (m) arr = JSON.parse(m[0]);
} catch (e) { arr = []; }
if ((!Array.isArray(arr) || arr.length === 0) && raw.indexOf('[') !== -1) {
  try {
    const start = raw.indexOf('[');
    const lastObj = raw.lastIndexOf('}');
    if (start !== -1 && lastObj > start) {
      arr = JSON.parse(raw.slice(start, lastObj + 1) + ']');
    }
  } catch (e) { arr = []; }
}
if (!Array.isArray(arr)) arr = [];
const rejected_reasons = {};
function bump(k) { rejected_reasons[k] = (rejected_reasons[k] || 0) + 1; }
const survivors = [];
for (const r of arr) {
  if (!r || r.is_idea === false) { bump('not_idea'); continue; }
  if (!r.idea || String(r.idea).trim().length < 12) { bump('title_too_short'); continue; }
  if (BLACKLIST.some(rx => rx.test(r.idea))) { bump('blacklisted_framing'); continue; }
  if (!r.pillar_id) { bump('no_pillar'); continue; }
  if (!r.source_url) { bump('no_source_url'); continue; }
  if (typeof r.brand_fit_score !== 'number' || r.brand_fit_score < minFit) { bump('below_min_fit'); continue; }
  if (!Array.isArray(r.evidence_present) || r.evidence_present.length === 0) { bump('no_evidence_listed'); continue; }
  survivors.push(r);
}
return [{ json: { survivors, survivors_count: survivors.length, rejected_count: arr.length - survivors.length, rejected_reasons, raw_count: arr.length, model_used, cost_usd: Math.round(cost_usd * 100000) / 100000 } }];

const d = ($input.first() && $input.first().json) || {};
const survivors = d.survivors || [];
return survivors.map(s => ({ json: s }));

const survivor = $('Loop Survivors').context.currentRunIndex !== undefined ? ($('Loop Survivors').item && $('Loop Survivors').item.json) : null;
const research = ($input.first() && $input.first().json) || {};
let contrarian = null;
let adjacent = [];
try {
  const txt = (research.choices && research.choices[0] && research.choices[0].message && research.choices[0].message.content) || '';
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) {
    const obj = JSON.parse(m[0]);
    contrarian = obj.contrarian || null;
    adjacent = Array.isArray(obj.adjacent_stories) ? obj.adjacent_stories : [];
  }
} catch (e) {}
const src = survivor || (($('Fan Survivors').first() && $('Fan Survivors').first().json) || {});
return [{ json: { ...src, contrarian, adjacent_stories: adjacent } }];

const listed = ($('Gmail Limit Ids').first().json.ids) || [];
const seen = new Set($input.all().map(i => i.json && i.json.gmail_message_id).filter(Boolean));
const unseen = listed.filter(id => !seen.has(id));
const CAP = 20;
const batch = unseen.slice(0, CAP);
const stats = { gmail_listed: listed.length, gmail_new: unseen.length, gmail_overflow: unseen.length - batch.length };
if (batch.length === 0) return [{ json: { _empty: true, ...stats } }];
return batch.map(id => ({ json: { id, ...stats } }));

const base = $('Gmail Extract Body').first().json;
let map = {};
try { const r = $input.first().json; if (r && typeof r === 'object' && !Array.isArray(r) && !r.error) map = r; } catch (e) {}
const newsletters = (base.newsletters || []).map(n => {
  const hit = map[n.from_email] || null;
  return { ...n, newsletter_key: hit ? hit.key : null, canonical_label: hit ? hit.label : (n.display_name || n.from_email || 'unknown') };
});
return [{ json: { newsletters, gmail_count: newsletters.length, gmail_listed: base.gmail_listed || 0, gmail_new: base.gmail_new || 0, gmail_overflow: base.gmail_overflow || 0 } }];
